('327', '7', 'Admin Lembaga Penjaminan Mutu (LPM)', 'super_admin', NULL, NULL, 'UPDATE', 'Kelola Beranda Publik', 'landing_settings', 'Konten Beranda & Footer Publik (37 item)', '{\"direktori_section_desc\":\"Pilih fakultas di bawah untuk meninjau profil kepemimpinan, sebaran dokumen mutu 5 siklus PPEPP, dan status kepatuhan standar mutu masing-masing prodi.\",\"direktori_section_tag\":\"DIREKTORI AKADEMIK\",\"direktori_section_title\":\"Fakultas & Program Studi\",\"footer_address\":\"Kampus Bendan Dhuwur, Jl. Pawiyatan Luhur IV\\/1, Semarang 50234\",\"footer_akreditasi\":\"Terakreditasi UNGGUL • BAN-PT\",\"footer_brand_sub\":\"Lembaga Penjamin Mutu UNIKA Soegijapranata\",\"footer_brand_title\":\"SPMI PPEPP\",\"footer_desc\":\"Sistem Informasi Manajemen Siklus PPEPP (Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan) mendukung transparansi penjaminan mutu tridharma perguruan tinggi dan akreditasi berkelanjutan.\",\"footer_email\":\"lpm@unika.ac.id\",\"footer_phone\":\"(024) 8441555 ext. 1402\",\"footer_website_text\":\"Website Utama SCU\",\"footer_website_url\":\"https:\\/\\/www.unika.ac.id\",\"hero_badge\":\"Lembaga Penjaminan Mutu • UNIKA Soegijapranata\",\"hero_btn1_text\":\"Jelajahi Direktori Fakultas\",\"hero_btn1_url\":\"#direktoriFakultas\",\"hero_btn2_text\":\"Repositori Dokumen Mutu\",\"hero_btn2_url\":\"dokumen\",\"hero_desc\":\"Portal terpadu pengawasan dan repositori dokumen Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan mutu tridharma di seluruh program studi Universitas Katolik Soegijapranata.\",\"hero_highlight\":\"Siklus PPEPP Berkelanjutan\",\"hero_title\":\"Sistem Penjaminan Mutu Internal\",\"siklus_e_desc\":\"Audit Mutu Internal (AMI), monitoring berkala, monev pembelajaran, dan pengukuran kepuasan pengguna.\",\"siklus_e_title\":\"Evaluasi\",\"siklus_p1_desc\":\"Perumusan standar, manual mutu, kebijakan SPMI, dan Capaian Pembelajaran Lulusan (CPL).\",\"siklus_p1_title\":\"Penetapan\",\"siklus_p2_desc\":\"Implementasi kurikulum, RPS, SOP pembelajaran, penelitian, dan pengabdian masyarakat prodi.\",\"siklus_p2_title\":\"Pelaksanaan\",\"siklus_p3_desc\":\"Tindakan koreksi terhadap deviasi standar, evaluasi akar masalah, dan Rapat Tinjauan Manajemen (RTM).\",\"siklus_p3_title\":\"Pengendalian\",\"siklus_p4_desc\":\"Pembaruan dan peningkatan standar mutu secara berkelanjutan (Kaizen) melampaui SN-Dikti.\",\"siklus_p4_title\":\"Peningkatan\",\"siklus_section_desc\":\"Implementasi siklus berkelanjutan (Continuous Quality Improvement) sesuai pedoman Permendikbudristek No. 53 Tahun 2023 untuk mencapai akreditasi unggul institusi.\",\"siklus_section_tag\":\"ALUR PENJAMINAN MUTU\",\"siklus_section_title\":\"5 Siklus Penjaminan Mutu Internal (PPEPP)\",\"stats_dokumen_label\":\"Dokumen Mutu Terverifikasi\",\"stats_fakultas_label\":\"Fakultas & Pascasarjana\",\"stats_prodi_label\":\"Program Studi Aktif\",\"stats_siklus_label\":\"Siklus PPEPP Terintegrasi\"}', '{\"direktori_section_desc\":\"Pilih fakultas di bawah untuk meninjau profil kepemimpinan, sebaran dokumen mutu 5 siklus PPEPP, dan status kepatuhan standar mutu masing-masing prodi.\",\"direktori_section_tag\":\"DIREKTORI AKADEMIK\",\"direktori_section_title\":\"Fakultas & Program Studi\",\"footer_address\":\"Kampus Bendan Dhuwur, Jl. Pawiyatan Luhur IV\\/1, Semarang 50234\",\"footer_akreditasi\":\"Terakreditasi UNGGUL • BAN-PT\",\"footer_brand_sub\":\"Lembaga Penjamin Mutu UNIKA Soegijapranata\",\"footer_brand_title\":\"SPMI PPEPP\",\"footer_desc\":\"Sistem Informasi Manajemen Siklus PPEPP (Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan) mendukung transparansi penjaminan mutu tridharma perguruan tinggi dan akreditasi berkelanjutan.\",\"footer_email\":\"lpm@unika.ac.id\",\"footer_phone\":\"(024) 8441555 ext. 1402\",\"footer_website_text\":\"Website Utama SCU\",\"footer_website_url\":\"https:\\/\\/www.unika.ac.id\",\"hero_badge\":\"Lembaga Penjaminan Mutu • UNIKA Soegijapranata [Updated by LPM]\",\"hero_btn1_text\":\"Je