('2', 'Standar Beban Kinerja Dosen dan Rasio Dosen-Mahasiswa Program Studi TI', 'prodi', '1', '2', '4', '17', '2024/2025', 'Pedoman pemetaan keahlian dosen, penelitian wajib, dan batas maksimal pembimbingan skripsi.', '22', '2026-09-16 13:36:03', '2026-10-15 11:35:32', NULL),
