('4', 'Laporan Hibah Riset Kolaborasi Dosen-Mahasiswa Bidang Artificial Intelligence', 'prodi', '1', '2', '7', '34', '2024/2025', 'Realisasi 6 proyek riset terapan Machine Learning bermitra dengan industri di Jawa Tengah.', '22', '2026-09-16 13:36:03', '2026-10-15 11:35:32', NULL),
('5', 'Laporan Hasil Audit Mutu Internal (AMI) Siklus XIX Program Studi Teknik Informatika', 'prodi', '1', '2', '2', '7', '2024/2025', 'Hasil temuan auditor internal mengenai kesesuaian sarana lab komputer dan ketepatan masa studi mahasiswa.', '22', '2026-09-16 13:36:03', '2026-10-15 11:35:32', NULL),
